import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { getBookingsForOwner, updateBookingStatus } from '../../api/listingService';
import { useNavigate } from 'react-router-dom';
import { toast } from "sonner";

import { Button } from "../../components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from "../../components/ui/dialog";

import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "../../components/ui/dropdown-menu";
import { Badge } from "../../components/ui/badge";
import { Input } from "../../components/ui/input";
import { Label } from "../../components/ui/label";
import { Clock, Check, X, MessageSquare, AlertCircle, User, MoreVertical, CalendarCheck, Home, Utensils, Calendar, Search } from 'lucide-react';
import { cn } from "../../lib/utils";
import Pagination from '../ui/Pagination';

const StatusBadge = ({ status }) => {
    const statusLower = status ? status.toLowerCase() : 'unknown';
    let variant = "secondary";
    let icon = null;
    let displayText = status;

    if (statusLower === 'pending') {
        variant = "warning";
        icon = <Clock className="h-3 w-3 mr-1" />;
    } else if (statusLower === 'approved_by_owner') {
        variant = "default";
        icon = <Check className="h-3 w-3 mr-1" />;
        displayText = "Approved - Awaiting Payment";
    } else if (statusLower === 'confirmed') {
        variant = "success";
        icon = <Check className="h-3 w-3 mr-1" />;
        displayText = "Confirmed & Paid";
    } else if (statusLower === 'cancelled' || statusLower === 'rejected') {
        variant = "destructive";
        icon = <X className="h-3 w-3 mr-1" />;
        displayText = statusLower === 'rejected' ? "Rejected" : "Cancelled";
    } else if (statusLower === 'expired') {
        variant = "outline";
        icon = <AlertCircle className="h-3 w-3 mr-1" />;
        displayText = "Expired";
    }

    return (
        <Badge variant={variant} className="flex items-center py-1 px-2 text-xs font-medium">
            {icon}
            {displayText}
        </Badge>
    );
};

const CountdownTimer = ({ expiryTime }) => {
    const calculateTimeLeft = useCallback(() => {
        if (!expiryTime) return { hours: 0, minutes: 0 };
        const difference = new Date(expiryTime) - new Date();
        let timeLeft = {};

        if (difference > 0) {
            timeLeft = {
                hours: Math.floor((difference / (1000 * 60 * 60)) % 24),
                minutes: Math.floor((difference / 1000 / 60) % 60),
            };
        } else {
            timeLeft = { hours: 0, minutes: 0 };
        }

        return timeLeft;
    }, [expiryTime]);

    const [timeLeft, setTimeLeft] = useState(calculateTimeLeft());

    useEffect(() => {
        const timer = setTimeout(() => {
            setTimeLeft(calculateTimeLeft());
        }, 1000);

        return () => clearTimeout(timer);
    }, [expiryTime, calculateTimeLeft]);

    const { hours, minutes } = timeLeft;
    const isExpired = hours <= 0 && minutes <= 0;

    if (isExpired) return null;

    return (
        <div className="text-xs mt-1 flex items-center">
            <Clock className="h-3 w-3 mr-1 text-amber-600" />
            <span className="font-medium text-amber-700">
                {hours}h {minutes}m left
            </span>
        </div>
    );
};

const ActionMenu = ({ booking, onApprove, onReject }) => (
    <DropdownMenu>
        <DropdownMenuTrigger asChild>
            <Button variant="ghost" className="h-8 w-8 p-0">
                <span className="sr-only">Open menu</span>
                <MoreVertical className="h-4 w-4" />
            </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end">
            {booking.status === 'pending' && (
                <>
                    <DropdownMenuItem onClick={() => onApprove(booking.booking_id)}>
                        <Check className="mr-2 h-4 w-4 text-green-500" />
                        Approve for Payment
                    </DropdownMenuItem>
                    <DropdownMenuItem onClick={() => onReject(booking.booking_id)} className="text-red-600 focus:text-red-600">
                        <X className="mr-2 h-4 w-4 text-red-500" />
                        Reject Booking
                    </DropdownMenuItem>
                </>
            )}
            <DropdownMenuItem>
                <MessageSquare className="mr-2 h-4 w-4 text-blue-500" />
                Contact Student
            </DropdownMenuItem>
        </DropdownMenuContent>
    </DropdownMenu>
);

const OwnerBookings = () => {
    const navigate = useNavigate();
    const [bookings, setBookings] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [activeFilter, setActiveFilter] = useState('all');
    const [searchQuery, setSearchQuery] = useState('');
    const [openReject, setOpenReject] = useState(null);
    const [rejectionReason, setRejectionReason] = useState('');
    const [currentPage, setCurrentPage] = useState(1);
    const itemsPerPage = 8;

    const fetchBookings = async () => {
        try {
            setLoading(true);
            const data = await getBookingsForOwner();
            setBookings(Array.isArray(data) ? data : []);
            setError('');
        } catch (err) {
            setError("Failed to fetch owner bookings. Please refresh the page.");
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchBookings();
    }, []);

    const handleUpdateStatus = useCallback(async (bookingId, status, reason = '') => {
        setBookings(prev => prev.map(b =>
            b.booking_id === bookingId ? { ...b, status: status } : b
        ));

        try {
            await updateBookingStatus(bookingId, status, reason);
            toast.success(`Booking ${bookingId.substring(0, 8)}... has been ${status}.`);
            setOpenReject(prev => prev === bookingId ? null : prev);
        } catch (err) {
            toast.error(err.message || 'Failed to update booking status.');
            fetchBookings();
        }
    }, []);

    const handleApprove = useCallback((bookingId) => {
        handleUpdateStatus(bookingId, 'approved_by_owner');
    }, [handleUpdateStatus]);

    const handleRejectClick = useCallback((bookingId) => {
        setOpenReject(bookingId);
    }, []);

    // Filter and search logic
    const filteredBookings = bookings.filter(booking => {
        const statusLower = booking.status?.toLowerCase();
        const normalizedStatus = statusLower === 'approved_by_owner' ? 'approved' : statusLower;
        const matchesFilter = activeFilter === 'all' || normalizedStatus === activeFilter;
        const matchesSearch = booking.itemName?.toLowerCase().includes(searchQuery.toLowerCase()) ||
            booking.studentName?.toLowerCase().includes(searchQuery.toLowerCase());
        return matchesFilter && matchesSearch;
    });

    // Paginate bookings
    const paginatedBookings = useMemo(() => {
        const startIndex = (currentPage - 1) * itemsPerPage;
        return filteredBookings.slice(startIndex, startIndex + itemsPerPage);
    }, [filteredBookings, currentPage]);

    const handlePageChange = (page) => {
        setCurrentPage(page);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    // Reset page when filter changes
    useEffect(() => {
        setCurrentPage(1);
    }, [activeFilter, searchQuery]);

    if (loading) {
        return (
            <div className="bg-white p-6 shadow-lg rounded-lg border border-gray-200">
                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
                    <div className="flex items-center gap-3">
                        <div className="w-12 h-12 bg-gray-200 rounded-lg animate-pulse"></div>
                        <div>
                            <div className="h-7 w-40 bg-gray-200 rounded animate-pulse mb-1"></div>
                            <div className="h-4 w-52 bg-gray-200 rounded animate-pulse"></div>
                        </div>
                    </div>
                    <div className="h-10 w-40 bg-gray-200 rounded animate-pulse"></div>
                </div>
                <div className="flex flex-wrap gap-2 mb-6">
                    {[1, 2, 3, 4, 5, 6, 7].map(i => (
                        <div key={i} className="h-9 w-20 bg-gray-200 rounded animate-pulse"></div>
                    ))}
                </div>
                <div className="space-y-4">
                    {[1, 2, 3, 4, 5].map(i => (
                        <div key={i} className="border rounded-xl p-4 bg-gray-50 animate-pulse">
                            <div className="flex items-start gap-4">
                                <div className="w-16 h-16 bg-gray-200 rounded-lg"></div>
                                <div className="flex-1">
                                    <div className="h-5 w-40 bg-gray-200 rounded mb-2"></div>
                                    <div className="h-4 w-56 bg-gray-200 rounded mb-2"></div>
                                    <div className="h-4 w-32 bg-gray-200 rounded"></div>
                                </div>
                            </div>
                            <div className="flex gap-2 mt-4">
                                <div className="h-9 flex-1 bg-gray-200 rounded"></div>
                                <div className="h-9 w-24 bg-gray-200 rounded"></div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        );
    }

    const rejectingBooking = bookings.find(b => b.booking_id === openReject);

    return (
        <div className="bg-white p-6 shadow-lg rounded-lg border border-gray-200">
            {/* Header */}
            <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4 mb-6">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-green-50 rounded-lg">
                        <CalendarCheck className="text-green-600 h-6 w-6" />
                    </div>
                    <div>
                        <h3 className="text-2xl font-bold text-gray-800">Booking Management</h3>
                        <p className="text-gray-500 text-sm">Manage your incoming booking requests</p>
                    </div>
                </div>
                <div className="relative">
                    <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
                    <Input
                        placeholder="Search bookings..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="pl-10 max-w-xs"
                    />
                </div>
            </div>

            {/* Status Filters */}
            <div className="flex flex-wrap gap-2 mb-6">
                {[
                    { label: "All", value: "all", statuses: ["pending", "approved_by_owner", "confirmed", "cancelled", "rejected", "expired"] },
                    { label: "Pending", value: "pending", statuses: ["pending"] },
                    { label: "Approved", value: "approved", statuses: ["approved_by_owner"] },
                    { label: "Confirmed", value: "confirmed", statuses: ["confirmed"] },
                    { label: "Cancelled", value: "cancelled", statuses: ["cancelled"] },
                    { label: "Rejected", value: "rejected", statuses: ["rejected"] },
                    { label: "Expired", value: "expired", statuses: ["expired"] },
                ].map(({ label, value, statuses }) => {
                    const count = bookings.filter(b => statuses.includes(b.status?.toLowerCase())).length;
                    return (
                        <Button
                            key={value}
                            variant={activeFilter === value ? "default" : "outline"}
                            className={cn(
                                activeFilter === value
                                    ? "bg-green-600 hover:bg-green-700 text-white"
                                    : "border-green-300 text-green-700 hover:bg-green-50"
                            )}
                            onClick={() => setActiveFilter(value)}
                        >
                            {label}
                            {count > 0 && (
                                <span className={cn(
                                    "ml-2 px-2 py-0.5 rounded-full text-xs",
                                    activeFilter === value ? "bg-green-700" : "bg-green-100"
                                )}>
                                    {count}
                                </span>
                            )}
                        </Button>
                    );
                })}
            </div>

            {/* Error Message */}
            {error && <p className="text-sm text-red-600 mb-3">{error}</p>}

            {/* Card Grid Container - Replace Table */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {/* Map through paginated bookings to create cards */}
                {paginatedBookings.length > 0 ? (
                    paginatedBookings.map(booking => (
                        // Booking Card Component
                        <div
                            key={booking.booking_id}
                            className={cn(
                                "border-l-4 rounded-xl p-4 shadow-sm transition-all duration-200 hover:shadow-md",
                                booking.status.toLowerCase() === 'pending' && "border-amber-400 bg-amber-50",
                                booking.status.toLowerCase() === 'approved_by_owner' && "border-blue-500 bg-blue-50",
                                booking.status.toLowerCase() === 'confirmed' && "border-green-500 bg-green-50",
                                (booking.status.toLowerCase() === 'cancelled' || booking.status.toLowerCase() === 'rejected') && "border-red-500 bg-red-50",
                                booking.status.toLowerCase() === 'expired' && "border-gray-400 bg-gray-100"
                            )}
                        >
                            {/* Card Header - Student Info */}
                            <div className="flex items-start gap-3 mb-3">
                                {booking.studentPhoto ? (
                                    <img
                                        src={booking.studentPhoto}
                                        alt={booking.studentName}
                                        className="w-12 h-12 rounded-full object-cover border-2 border-gray-200"
                                    />
                                ) : (
                                    <div className="bg-green-100 rounded-full w-12 h-12 flex items-center justify-center">
                                        <User className="text-green-600 h-6 w-6" />
                                    </div>
                                )}
                                <div className="flex-1 min-w-0">
                                    <h4 className="font-semibold text-gray-900 truncate">{booking.studentName}</h4>
                                    <p className="text-sm text-gray-600 truncate">{booking.studentCollege || "Student"}</p>
                                    {booking.studentPhone && (
                                        <p className="text-xs text-gray-500">{booking.studentPhone}</p>
                                    )}
                                </div>
                            </div>

                            {/* Card Body - Booking Details */}
                            <div className="space-y-2 mb-4">
                                <div className="flex items-center gap-2 text-sm">
                                    {booking.item_type === 'room' ? (
                                        <Home className="h-4 w-4 text-blue-600" />
                                    ) : (
                                        <Utensils className="h-4 w-4 text-orange-600" />
                                    )}
                                    <span className="font-medium text-gray-900">{booking.itemName}</span>
                                </div>
                                <div className="flex items-center gap-2 text-sm text-gray-600">
                                    <Calendar className="h-4 w-4" />
                                    <span>Start: {booking.start_date}</span>
                                </div>
                                <div className="flex items-center gap-2 text-sm">
                                    <Badge variant="secondary" className={cn(
                                        booking.item_type === 'room' ? "bg-blue-100 text-blue-800" : "bg-orange-100 text-orange-800"
                                    )}>
                                        {booking.item_type === 'room' ? <Home className="h-3 w-3 mr-1" /> : <Utensils className="h-3 w-3 mr-1" />}
                                        {booking.item_type}
                                    </Badge>
                                    {booking.gender && (
                                        <Badge variant="outline">{booking.gender}</Badge>
                                    )}
                                </div>
                                {booking.note && (
                                    <div className="text-sm bg-gray-50 p-2 rounded-lg">
                                        <div className="flex items-start gap-2">
                                            <MessageSquare className="h-3 w-3 text-blue-500 mt-0.5" />
                                            <p className="text-gray-700 text-xs">{booking.note}</p>
                                        </div>
                                    </div>
                                )}
                            </div>

                            {/* Card Footer - Status & Actions */}
                            <div className="flex flex-col gap-2">
                                <div className="flex items-center justify-between">
                                    <div className="flex flex-col">
                                        <StatusBadge status={booking.status} />
                                        {(booking.status.toLowerCase() === 'approved_by_owner' || booking.status.toLowerCase() === 'confirmed') && booking.expiryTime && (
                                            <CountdownTimer expiryTime={booking.expiryTime} />
                                        )}
                                    </div>
                                    <ActionMenu booking={booking} onApprove={handleApprove} onReject={handleRejectClick} />
                                </div>

                                {/* Action Buttons for Pending */}
                                {booking.status === 'pending' && (
                                    <div className="flex gap-2 mt-2">
                                        <Button
                                            variant="default"
                                            className="flex-1 bg-green-600 hover:bg-green-700 text-white"
                                            onClick={() => handleUpdateStatus(booking.booking_id, 'approved_by_owner')}
                                        >
                                            <Check className="h-4 w-4 mr-2" />
                                            Approve for Payment
                                        </Button>
                                        <Button
                                            variant="destructive"
                                            className="flex-1"
                                            onClick={() => setOpenReject(booking.booking_id)}
                                        >
                                            <X className="h-4 w-4 mr-2" />
                                            Reject
                                        </Button>
                                    </div>
                                )}
                            </div>
                        </div>
                    ))
                ) : (
                    // Empty State - Replace table empty row
                    <div className="col-span-full flex flex-col items-center justify-center text-center p-12">
                        <div className="relative mb-6">
                            <div className="absolute inset-0 bg-green-100 rounded-full animate-pulse"></div>
                            <div className="relative bg-white p-4 rounded-full shadow-lg">
                                {activeFilter === 'pending' ? (
                                    <Clock className="h-12 w-12 text-amber-500" />
                                ) : activeFilter === 'approved' ? (
                                    <Check className="h-12 w-12 text-blue-500" />
                                ) : activeFilter === 'confirmed' ? (
                                    <Check className="h-12 w-12 text-green-500" />
                                ) : activeFilter === 'cancelled' || activeFilter === 'rejected' ? (
                                    <X className="h-12 w-12 text-red-500" />
                                ) : activeFilter === 'expired' ? (
                                    <AlertCircle className="h-12 w-12 text-gray-500" />
                                ) : (
                                    <CalendarCheck className="h-12 w-12 text-green-500" />
                                )}
                            </div>
                        </div>
                        <h3 className="text-xl font-bold text-gray-800 mb-2">
                            {activeFilter === 'all' ? 'No Booking Requests Yet' : `No ${activeFilter.charAt(0).toUpperCase() + activeFilter.slice(1)} Bookings`}
                        </h3>
                        <p className="text-gray-500 max-w-md mb-6">
                            {activeFilter === 'all'
                                ? "When students send booking requests for your listings, they'll appear here."
                                : `You don't have any ${activeFilter} bookings at the moment.`}
                        </p>
                        {activeFilter === 'all' && (
                            <Button
                                className="bg-green-600 hover:bg-green-700 text-white font-medium px-6 py-2"
                                onClick={() => navigate('/dashboard/create-room')}
                            >
                                Create Your First Listing
                            </Button>
                        )}
                    </div>
                )}
            </div>

            <Pagination
                currentPage={currentPage}
                totalItems={filteredBookings.length}
                itemsPerPage={itemsPerPage}
                onPageChange={handlePageChange}
            />

            {/* Rejection Confirmation Dialog - rendered alongside the list, not replacing it */}
            <Dialog open={!!openReject} onOpenChange={() => { setOpenReject(null); setRejectionReason(''); }}>
                <DialogContent>
                    <DialogHeader>
                        <DialogTitle>Reject Booking</DialogTitle>
                    </DialogHeader>
                    <div className="py-4">
                        <p className="text-gray-600 mb-4">
                            Are you sure you want to reject the booking request from {rejectingBooking?.studentName || 'this student'}?
                        </p>
                        <div className="mb-4">
                            <Label className="block text-sm font-medium text-gray-700 mb-2">
                                Reason for rejection (optional):
                            </Label>
                            <Input
                                value={rejectionReason}
                                onChange={(e) => setRejectionReason(e.target.value)}
                                placeholder="Enter reason..."
                                className="w-full"
                            />
                        </div>
                    </div>
                    <DialogFooter>
                        <Button
                            variant="outline"
                            onClick={() => {
                                setOpenReject(null);
                                setRejectionReason('');
                            }}
                        >
                            Cancel
                        </Button>
                        <Button
                            onClick={() => handleUpdateStatus(openReject, 'rejected', rejectionReason)}
                            className="bg-red-600 hover:bg-red-700"
                        >
                            Reject Booking
                        </Button>
                    </DialogFooter>
                </DialogContent>
            </Dialog>
        </div>
    );
};

export default OwnerBookings;